function paragrafosDaAnalise(texto) {
  const paragrafos = texto.split(/\n\s*\n/).map((paragrafo) => paragrafo.trim()).filter(Boolean);
  return paragrafos.length > 0 ? paragrafos : [texto];
}
function afirmacoesDaIntroducao(texto) {
  return paragrafosDaAnalise(texto).map((paragrafo) => ({
    texto: paragrafo,
    sustentadaPor: []
  }));
}
function aplicarIntroducaoAprovada(snapshot, texto) {
  if (typeof texto !== "string" || texto.trim() === "") return snapshot;
  return {
    ...snapshot,
    leitura: {
      ...snapshot.leitura,
      resumoExecutivo: afirmacoesDaIntroducao(texto)
    }
  };
}
function introducaoDasAnalises(analises) {
  const introducao = analises.find((analise) => analise.secao === "introducao");
  return introducao?.texto ?? null;
}

